"use client";

import { ClipboardPaste, Eraser, Sparkles } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Textarea } from "@/components/ui/textarea";
import { toast } from "@/components/ui/toast";
import { MAX_CHARS } from "@/components/tts-provider";

const SAMPLE_TEXT =
  "Hello! Welcome to FreeTTS. Everything you hear is generated by artificial intelligence running entirely on your device — no servers, no accounts, no fees. Try changing the voice, or adjusting the speaking speed.";

/**
 * Rough speech rate behind the duration estimate: ~850 characters per
 * minute at 1× for English. It is labelled an estimate everywhere it
 * appears — real timing depends on the voice and the text.
 */
const CHARS_PER_MIN = 850;

export function durationEstimate(
  charCount: number,
  speed: number,
): string | null {
  if (charCount === 0) return null;
  const mins = charCount / CHARS_PER_MIN / Math.max(speed, 0.1);
  if (mins < 1) return "< 1 min";
  return mins < 10 ? `${mins.toFixed(1)} min` : `${Math.round(mins)} min`;
}

export function TextEditor({
  text,
  onChange,
  disabled,
  speed,
}: {
  text: string;
  onChange: (t: string) => void;
  disabled?: boolean;
  /** Current speaking speed — the duration estimate accounts for it. */
  speed: number;
}) {
  const count = text.length;
  const over = count > MAX_CHARS;
  const words = text.trim() === "" ? 0 : text.trim().split(/\s+/).length;
  const estimate = durationEstimate(count, speed);

  const paste = async () => {
    try {
      const clip = await navigator.clipboard.readText();
      if (!clip) {
        toast("Clipboard is empty", {
          description: "Copy some text first, then paste.",
        });
        return;
      }
      onChange(text === "" ? clip : `${text}${/\s$/.test(text) ? "" : " "}${clip}`);
    } catch {
      toast.error("Couldn't read the clipboard", "Your browser blocked clipboard access — paste with Ctrl/⌘ + V instead.");
    }
  };

  return (
    <section aria-label="Text to speak" className="space-y-3">
      <div className="flex flex-wrap items-baseline justify-between gap-2">
        <h2 className="text-sm font-medium">Text to speak</h2>
        <p className="text-xs tabular-nums text-muted-foreground">
          {words.toLocaleString()} {words === 1 ? "word" : "words"}
          {estimate && (
            <>
              {" · "}≈ {estimate} <span className="italic">estimate</span>
            </>
          )}
          {" · "}
          <span className={over ? "font-medium text-destructive" : undefined}>
            {count.toLocaleString()} / {MAX_CHARS.toLocaleString()}
          </span>
        </p>
      </div>
      <Textarea
        value={text}
        onChange={(e) => onChange(e.target.value)}
        disabled={disabled}
        placeholder="Type or paste text here…"
        className="min-h-64 resize-y text-base leading-relaxed"
        aria-label="Text to convert to speech"
        aria-describedby="studio-char-limit"
        // The draft is restored from localStorage on the client only — the
        // server always renders empty. This is an expected, benign mismatch.
        suppressHydrationWarning
      />
      <div className="flex flex-wrap items-center gap-2">
        <Button
          variant="outline"
          size="sm"
          onClick={() => onChange("")}
          disabled={disabled || count === 0}
        >
          <Eraser className="mr-1.5 h-3.5 w-3.5" /> Clear
        </Button>
        <Button variant="outline" size="sm" onClick={paste} disabled={disabled}>
          <ClipboardPaste className="mr-1.5 h-3.5 w-3.5" /> Paste
        </Button>
        <Button
          variant="outline"
          size="sm"
          onClick={() => onChange(SAMPLE_TEXT)}
          disabled={disabled}
        >
          <Sparkles className="mr-1.5 h-3.5 w-3.5" /> Try sample text
        </Button>
        <span id="studio-char-limit" className="sr-only">
          Text is limited to {MAX_CHARS.toLocaleString()} characters.
        </span>
      </div>
      {over && (
        <p role="alert" className="text-sm text-destructive">
          Text is too long — split it into smaller parts (limit{" "}
          {MAX_CHARS.toLocaleString()} characters).
        </p>
      )}
    </section>
  );
}
